# 按目标类型分发转换逻辑，严格校验布尔与列表格式
def parse_config_value(value: str, target_type: str):
    if target_type == 'int':
        return int(value)
    elif target_type == 'float':
        return float(value)
    elif target_type == 'bool':
        low = value.strip().lower()
        if low in ('true', 'yes', '1'):
            return True
        elif low in ('false', 'no', '0'):
            return False
        else:
            raise ValueError(f"cannot parse '{value}' as bool")
    elif target_type == 'str':
        return value
    elif target_type == 'list[int]':
        parts = [p.strip() for p in value.split(',') if p.strip()]
        if not parts:
            raise ValueError('empty list')
        result = []
        for p in parts:
            result.append(int(p))
        return result
    else:
        raise ValueError(f"unsupported type: {target_type}")

# 【算法思路】按日志严重等级权重过滤掉低于最低阈值的日志，并按时间戳升序输出。
