# 【算法思路】利用闭包字典与访问顺序列表实现容量受限的 LRU 函数结果缓存装饰器。
import functools

# 构建缓存装饰器维护最近 max_size 次调用键与命中统计
def memoize_n(max_size: int):
    # LRU 缓存装饰器工厂：保留最近 max_size 次不同参数组合的返回值
    if max_size <= 0:
        raise ValueError('max_size must be positive')
    def decorator(func):
        cache = {}
        order = []
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            if key in cache:
                order.remove(key)
                order.append(key)
                return {'result': cache[key], 'cached': True}
            result = func(*args, **kwargs)
            cache[key] = result
            order.append(key)
            if len(order) > max_size:
                oldest = order.pop(0)
                del cache[oldest]
            return {'result': result, 'cached': False}
        return wrapper
    return decorator

# 评测入口（请勿修改）
def eval_memoize(max_size: int, calls: list[list[int]]) -> list[dict]:
    @memoize_n(max_size)
    def add(a, b):
        return a + b
    return [add(*pair) for pair in calls]

# 【算法思路】以固定长度窗口在数值序列上右移切片，逐窗口输出均值、最大值与最小值。
# 校验窗口尺寸并切片计算每个窗口的三项统计量
def sliding_window_stats(numbers: list[float], window_size: int) -> list[dict]:
    if window_size <= 0:
        raise ValueError('window_size must be positive')
    if len(numbers) < window_size:
        return []
    result = []
    for i in range(len(numbers) - window_size + 1):
        window = numbers[i:i + window_size]
        avg = round(sum(window) / window_size, 2)
        result.append({'avg': avg, 'max': max(window), 'min': min(window)})
    return result

# 【算法思路】递归深合并两个嵌套字典：子字典继续向下合并，标量按 overwrite/ignore/merge 策略处理。
# 克隆基础字典并按冲突策略递归合并覆盖键值
def deep_merge(base: dict, override: dict, conflict: str = 'overwrite') -> dict:
    if conflict not in ('overwrite', 'ignore', 'merge'):
        raise ValueError(f"unknown conflict strategy: {conflict}")
    result = base.copy()
    for key, val in override.items():
        if key not in result:
            result[key] = val
        elif isinstance(result[key], dict) and isinstance(val, dict):
            result[key] = deep_merge(result[key], val, conflict)
        elif conflict == 'overwrite':
            result[key] = val
        elif conflict == 'ignore':
            pass
        elif conflict == 'merge':
            result[key] = val
    return result

