# 将下划线风格字段名转为小驼峰
def snake_to_camel(name: str) -> str:
    parts = name.split('_')
    return parts[0] + ''.join(p.capitalize() for p in parts[1:])

# 遍历字典递归清洗键值类型并过滤空值
def clean_json_record(record: dict) -> dict:
    result = {}
    for key, val in record.items():
        new_key = snake_to_camel(key)
        if isinstance(val, dict):
            val = clean_json_record(val)
        elif isinstance(val, str):
            val = val.strip()
            if val == '':
                continue
            if val.lower() in ('true', 'True'):
                val = True
            elif val.lower() in ('false', 'False'):
                val = False
            elif val == 'null':
                continue
            else:
                try:
                    if '.' in val:
                        val = float(val)
                    else:
                        val = int(val)
                except (ValueError, TypeError):
                    pass
        if val is not None:
            result[new_key] = val
    return result

# 【算法思路】按指定分组字段聚合记录并支持 sum/avg/count/max/min 五种聚合算子，结果降序排列。
# 分桶收集数值后按聚合函数计算指标并按结果降序排列
def group_aggregate(data: list[dict], group_by: str, agg_field: str, agg_func: str) -> list[dict]:
    if agg_func not in ('sum', 'avg', 'count', 'max', 'min'):
        raise ValueError(f"unsupported agg_func: {agg_func}")
    groups = {}
    for row in data:
        key = row.get(group_by)
        val = row.get(agg_field, 0)
        if key not in groups:
            groups[key] = {'vals': [], 'count': 0}
        groups[key]['vals'].append(val if val is not None else 0)
        groups[key]['count'] += 1
    result = []
    for key, info in groups.items():
        vals = info['vals']
        if agg_func == 'sum':
            agg_val = sum(vals)
        elif agg_func == 'avg':
            agg_val = round(sum(vals) / len(vals), 2) if vals else 0
        elif agg_func == 'count':
            agg_val = info['count']
        elif agg_func == 'max':
            agg_val = max(vals)
        elif agg_func == 'min':
            agg_val = min(vals)
        result.append({group_by: key, agg_field: agg_val, 'count': info['count']})
    result.sort(key=lambda x: x[agg_field], reverse=True)
    return result

