# 【算法思路】利用空闲队列与占用集合模拟连接池的获取、归还、超时等待及关闭状态隔离。
import time

# 管理空闲与活跃连接 ID 集合并提供超时等待获取逻辑
class ConnectionPool:
    """基于空闲栈与占用集合的简易数据库连接池"""
    def __init__(self, max_size: int):
        if max_size <= 0:
            raise ValueError('max_size must be positive')
        # 使用 pop() 从尾部分配，初始化倒序使首个 acquire 返回连接 1
        self._idle = list(range(max_size, 0, -1))
        self._busy = set()
        self._closed = False

    def acquire(self, timeout: float = 5.0) -> int:
        if self._closed:
            raise RuntimeError('pool is closed')
        if self._idle:
            conn = self._idle.pop()
            self._busy.add(conn)
            return conn
        if timeout <= 0:
            raise TimeoutError('no available connection')
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            if self._closed:
                raise RuntimeError('pool is closed')
            if self._idle:
                conn = self._idle.pop()
                self._busy.add(conn)
                return conn
            time.sleep(0.01)
        raise TimeoutError('acquire timed out')

    def release(self, conn: int) -> None:
        if conn in self._busy:
            self._busy.remove(conn)
            self._idle.append(conn)

    def close_all(self) -> None:
        self._closed = True
        self._idle.clear()
        self._busy.clear()

# 评测入口（请勿修改）
def eval_pool(max_size: int, actions: list[dict]) -> list:
    pool = ConnectionPool(max_size)
    out = []
    for act in actions:
        op = act.get("op")
        if op == "acquire":
            try:
                out.append(pool.acquire(act.get("timeout", 5.0)))
            except TimeoutError:
                out.append("timeout_error")
            except RuntimeError:
                out.append("closed_error")
        elif op == "release":
            pool.release(act["conn"])
            out.append(None)
        elif op == "close_all":
            pool.close_all()
            out.append(None)
    return out

